{"explanation":"The law of cosines is the Pythagorean theorem with a correction for the angle between two sides: a² = b² + c² − 2bc cos θ. Dropping a perpendicular gives a right triangle with legs c − b cos θ and b sin θ; applying Pythagoras and expanding produces the correction term. For an acute angle it subtracts, for an obtuse angle it adds, and at 90° it vanishes—leaving a² = b² + c².","manimCode":"const title = new Text({ text: 'Pythagoras + an angle correction', fontSize: 30, color: WHITE });
title.moveTo([0, 3.15, 0]);
const bLen = 2.8;
const cLen = 4;
let degrees = 55;
const origin = [-4.6, -1.35, 0];
const endB = [-0.6, -1.35, 0];
function geometry() {
  const angle = degrees * Math.PI / 180;
  const endC = [origin[0] + bLen * Math.cos(angle), origin[1] + bLen * Math.sin(angle), 0];
  const foot = [endC[0], origin[1], 0];
  return { angle, endC, foot };
}
const initial = geometry();
const triangle = new Polygon({ vertices: [origin, endB, initial.endC], color: WHITE });
triangle.setFill(BLUE_E, 0.13).setStrokeWidth(1);
function segment(p, q, color) {
  const obj = new Polygon({ vertices: [p, q], color });
  obj.setFillOpacity(0).setStrokeWidth(3);
  return obj;
}
const sideB = segment(origin, initial.endC, GREEN);
const sideC = segment(origin, endB, BLUE);
const sideA = segment(endB, initial.endC, YELLOW);
const altitude = segment(initial.endC, initial.foot, PURPLE);
altitude.setStrokeWidth(2);
const projection = segment(origin, initial.foot, PURPLE);
projection.setStrokeWidth(5);
const rightMark = new Polygon({ vertices: [[0,0,0], [0.1,0,0]], color: PURPLE });
rightMark.setFillOpacity(0).setStrokeWidth(2);
const tip = new Dot({ point: initial.endC, color: WHITE });
const labelA = new Text({ text: 'a', fontSize: 26, color: YELLOW });
const labelB = new Text({ text: 'b', fontSize: 26, color: GREEN });
const labelC = new Text({ text: 'c', fontSize: 26, color: BLUE });
labelC.moveTo([-2.6, -1.85, 0]);
const thetaLabel = new MathTex({ latex: '\\theta', color: ORANGE });
await thetaLabel.waitForRender();
thetaLabel.scale(0.65);
const angleWedge = new Polygon({ vertices: [origin, [origin[0]+0.5, origin[1],0], [origin[0]+0.3, origin[1]+0.3,0]], color: ORANGE });
angleWedge.setFill(ORANGE, 0.18).setStrokeWidth(1);
const projectionFormula = new MathTex({ latex: 'x=b\\cos\\theta,\\quad h=b\\sin\\theta', color: PURPLE });
await projectionFormula.waitForRender();
projectionFormula.scale(0.65).moveTo([3, 1.8, 0]);
const pythagoras = new MathTex({ latex: 'a^2=(c-b\\cos\\theta)^2+(b\\sin\\theta)^2' });
await pythagoras.waitForRender();
pythagoras.scale(0.57).moveTo([3, 0.85, 0]);
const identity = new MathTex({ latex: '\\sin^2\\theta+\\cos^2\\theta=1', color: GRAY });
await identity.waitForRender();
identity.scale(0.65).moveTo([3, 0.05, 0]);
const result = new MathTex({ latex: 'a^2=b^2+c^2\\underbrace{-2bc\\cos\\theta}_{\\text{angle correction}}' });
await result.waitForRender();
result.scale(0.82).moveTo([-1.6, -2.85, 0]);
let status;
function updateGeometry() {
  const g = geometry();
  triangle.setVertices([origin, endB, g.endC]);
  sideB.setVertices([origin, g.endC]);
  sideA.setVertices([endB, g.endC]);
  altitude.setVertices([g.endC, g.foot]);
  projection.setVertices([origin, g.foot]);
  const f = g.foot;
  rightMark.setVertices([[f[0]+0.16, f[1],0], [f[0]+0.16, f[1]+0.16,0], [f[0], f[1]+0.16,0]]);
  tip.moveTo(g.endC);
  labelB.moveTo([(origin[0]+g.endC[0])/2-0.3, (origin[1]+g.endC[1])/2+0.13,0]);
  labelA.moveTo([(endB[0]+g.endC[0])/2+0.28, (endB[1]+g.endC[1])/2+0.1,0]);
  const wedgePoints = [origin];
  for (let i=0; i<=24; i++) {
    const t = g.angle*i/24;
    wedgePoints.push([origin[0]+0.48*Math.cos(t), origin[1]+0.48*Math.sin(t),0]);
  }
  angleWedge.setVertices(wedgePoints);
  thetaLabel.moveTo([origin[0]+0.77*Math.cos(g.angle/2), origin[1]+0.77*Math.sin(g.angle/2),0]);
  if (status) scene.remove(status);
  const correction = -2*bLen*cLen*Math.cos(g.angle);
  const nearZero = Math.abs(correction)<0.00001;
  const description = nearZero ? '90°: correction = 0' : degrees.toFixed(0)+'°: correction '+(correction<0 ? 'subtracts ' : 'adds ')+Math.abs(correction).toFixed(2);
  status = new Text({ text: description, fontSize: 21, color: nearZero ? GREEN : ORANGE });
  status.moveTo([3, -0.8, 0]);
  scene.add(status);
}
scene.add(title, triangle, sideB, sideC, sideA, altitude, projection, rightMark, angleWedge, tip, labelA, labelB, labelC, thetaLabel);
updateGeometry();
await scene.play(new FadeIn(projectionFormula));
await scene.play(new FadeIn(pythagoras), new FadeIn(identity));
await scene.play(new Write(result));
makeHoverable(triangle, scene, { hoverScale: 1, hoverOpacity: 0.3 });
const controls = new Controls(scene, { position: 'bottom-right', width: 250 });
controls.addSlider({ label: 'Included angle θ', min: 25, max: 115, step: 1, value: degrees, onChange: value => { degrees = value; updateGeometry(); } });
controls.addButton({ label: 'Show Pythagoras: θ = 90°', onClick: () => { degrees = 90; updateGeometry(); } });
await scene.wait(999999);"}

